"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9844],{93998:e=>{e.exports=JSON.parse('{"functions":[{"name":"isEmpty","desc":"Whether an icon asset should be treated as absent. Covers nil, the empty\\nstring, and the three ways a zero asset id shows up in the data (`\\"0\\"`,\\n`\\"rbxassetid://0\\"`, `\\"rbxasset://0\\"`) \u2014 all of which render as a blank\\nsquare rather than failing visibly.","params":[{"name":"icon","desc":"Asset id to test","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":41,"path":"src/Client/Util/ItemSlotIcon.luau"}},{"name":"apply","desc":"Points a slot\'s icon at `iconAsset`, or \u2014 when the asset is empty by\\n[ItemSlotIcon.isEmpty] \u2014 hides the icon and expands the name label to fill\\nthe cell.\\n\\nOn its first call for a given label it stashes the label\'s `Size`,\\n`Position` and `AnchorPoint` in `OriginalSize` / `OriginalPosition` /\\n`OriginalAnchorPoint` attributes, and restores from those when an icon is\\npresent again. That is what makes the switch reversible, so a slot can be\\nre-bound to a different item at any time.\\n\\n:::caution\\nThe stash happens on first call, so call this before mutating the label\'s\\ngeometry yourself \u2014 otherwise the \\"original\\" captured is already the\\nmodified one.\\n:::","params":[{"name":"icon","desc":"The slot\'s icon label","lua_type":"ImageLabel"},{"name":"nameLabel","desc":"The slot\'s name label, expanded when there is no icon","lua_type":"TextLabel"},{"name":"iconAsset","desc":"Icon asset id, or nil/empty for the no-icon layout","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":75,"path":"src/Client/Util/ItemSlotIcon.luau"}}],"properties":[],"types":[],"name":"ItemSlotIcon","desc":"Handles the one awkward case in item slot rendering: an item with no icon.\\n\\nA slot normally shows a small icon with the item name beneath it. When the\\nicon asset is missing there is a hole, so the name label instead expands\\nto fill the whole cell and the icon is hidden. [ItemSlotIcon.apply]\\nperforms that switch, and \u2014 importantly \u2014 can switch back, because it\\nstashes the label\'s original geometry in attributes the first time it\\ntouches it.\\n\\nCurrently used by the backpack and hotbar slots.\\n\\n:::note TODO\\nThe shop routes (`AnimalEggShopRoute`, `PropShopRoute`, `SeedShopRoute`,\\n`SellingMarketRoute`) still render slots by hand, so empty-icon items do\\nnot expand their name labels there. They should be migrated onto these\\nhelpers.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":26,"path":"src/Client/Util/ItemSlotIcon.luau"}}')}}]);